     7→// ===== Dashboard Data Structures =====
     8→
     9→struct DashboardConfig {
    10→    title: String,
    11→    refresh_interval_sec: i32,
    12→    max_history_rows: i32,
    13→    theme_bg: String,
    14→    theme_accent: String,
    15→    theme_pink: String,
    16→    theme_cyan: String,
    17→    theme_orange: String,
    18→    theme_yellow: String,
    19→    api_base_url: String
    20→}
    21→
    22→trait DashboardConfigCl {
    23→    fn clone(&self) -> DashboardConfig;
    24→}
    25→
    26→impl DashboardConfigCl for DashboardConfig {
    27→    fn clone(&self) -> DashboardConfig {
    28→        DashboardConfig {
    29→            title: self.title.clone(),
    30→            refresh_interval_sec: self.refresh_interval_sec,
    31→            max_history_rows: self.max_history_rows,
    32→            theme_bg: self.theme_bg.clone(),
    33→            theme_accent: self.theme_accent.clone(),
    34→            theme_pink: self.theme_pink.clone(),
    35→            theme_cyan: self.theme_cyan.clone(),
    36→            theme_orange: self.theme_orange.clone(),
    37→            theme_yellow: self.theme_yellow.clone(),
    38→            api_base_url: self.api_base_url.clone()
    39→        }
    40→    }
    41→}
    42→
    43→struct DashboardData {
    44→    deployment_state: DeploymentState,
    45→    aggregated_metrics: AggregatedMetrics,
    46→    recent_history: Vec<ExecutionRecord>,
    47→    pipeline_health: f32
    48→}
    49→
    50→trait DashboardDataCl {
    51→    fn clone(&self) -> DashboardData;
    52→}
    53→
    54→impl DashboardDataCl for DashboardData {
    55→    fn clone(&self) -> DashboardData {
    56→        let mut cloned_history = vec![];
    57→        for i in 0..self.recent_history.len() {
    58→            cloned_history.push(self.recent_history[i].clone());
    59→        }
    60→
    61→        DashboardData {
    62→            deployment_state: self.deployment_state.clone(),
    63→            aggregated_metrics: self.aggregated_metrics.clone(),
    64→            recent_history: cloned_history,
    65→            pipeline_health: self.pipeline_health
    66→        }
    67→    }
    68→}
    69→
    70→// ===== Dashboard Configuration =====
    71→
    72→fn create_dashboard_config() -> DashboardConfig {
    73→    DashboardConfig {
    74→        title: "Sovereign Workspace v5.0".to_string(),
    75→        refresh_interval_sec: 5i32,
    76→        max_history_rows: 10i32,
    77→        theme_bg: "#282a36".to_string(),
    78→        theme_accent: "#50fa7b".to_string(),
    79→        theme_pink: "#ff79c6".to_string(),
    80→        theme_cyan: "#8be9fd".to_string(),
    81→        theme_orange: "#ffb86c".to_string(),
    82→        theme_yellow: "#f1fa8c".to_string(),
    83→        api_base_url: "http://localhost:8080".to_string()
    84→    }
    85→}
