    87→// ===== HTML Rendering Functions =====
    88→
    89→fn render_html_head(config: DashboardConfig) -> String {
    90→    let mut html = String::new();
    91→    html.push_str("<!DOCTYPE html>\n");
    92→    html.push_str("<html>\n");
    93→    html.push_str("<head>\n");
    94→    html.push_str("  <meta charset=\"utf-8\" />\n");
    95→    html.push_str("  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\" />\n");
    96→    html.push_str("  <title>");
    97→    html.push_str(config.title.as_str());
    98→    html.push_str("</title>\n");
    99→    html.push_str("  <meta http-equiv=\"refresh\" content=\"");
   100→    html.push_str(&config.refresh_interval_sec.to_string());
   101→    html.push_str("\" />\n");
   102→    html.push_str("</head>\n");
   103→    html
   104→}
