   173→fn render_header_section(data: DashboardData) -> String {
   174→    let mut html = String::new();
   175→    html.push_str("  <div class=\"header\">\n");
   176→    html.push_str("    <h1>Sovereign Workspace v5.0</h1>\n");
   177→    html.push_str("    <span class=\"badge\">Health: ");
   178→    html.push_str(&(data.pipeline_health * 100.0f32).to_string());
   179→    html.push_str("%</span>\n");
   180→    html.push_str("    <span class=\"badge\">Runs: ");
   181→    html.push_str(&data.deployment_state.total_pipeline_runs.to_string());
   182→    html.push_str("</span>\n");
   183→    html.push_str("  </div>\n");
   184→    html
   185→}
