   187→fn render_ascii_bar(label: String, value: f32, max_value: f32, width: i32) -> String {
   188→    let filled = ((value / max_value) * (width as f32)) as i32;
   189→    let empty = width - filled;
   190→    let mut bar = String::new();
   191→    bar.push_str(label.as_str());
   192→    bar.push_str(" [");
   193→
   194→    for _i in 0..filled {
   195→        bar.push_str("█");
   196→    }
   197→    for _i in 0..empty {
   198→        bar.push_str("░");
   199→    }
   200→
   201→    bar.push_str("] ");
   202→    bar.push_str(&value.to_string());
   203→    bar.push_str("%\n");
   204→    bar
   205→}
