   207→fn render_single_agent_card(status: AgentStatus, color: String) -> String {
   208→    let mut html = String::new();
   209→    html.push_str("    <div class=\"card\" style=\"border-color: ");
   210→    html.push_str(color.as_str());
   211→    html.push_str("; \">\n");
   212→    html.push_str("      <h3>");
   213→    html.push_str(status.agent_name.as_str());
   214→    html.push_str("</h3>\n");
   215→    html.push_str("      <div class=\"status\">");
   216→    html.push_str(status.status.as_str());
   217→    html.push_str("</div>\n");
   218→    html.push_str("      <div class=\"rate\">Success: ");
   219→    html.push_str(&(status.success_rate * 100.0f32).to_string());
   220→    html.push_str("%</div>\n");
   221→    html.push_str("    </div>\n");
   222→    html
   223→}
   224→
   225→fn render_agent_cards_section(data: DashboardData) -> String {
   226→    let mut html = String::new();
   227→    html.push_str("  <div class=\"agent-grid\">\n");
   228→
   229→    let colors = vec![
   230→        "#50fa7b".to_string(),
   231→        "#8be9fd".to_string(),
   232→        "#ff79c6".to_string(),
   233→        "#ffb86c".to_string(),
   234→        "#f1fa8c".to_string()
   235→    ];
   236→
   237→    for i in 0..data.deployment_state.agent_statuses.len() {
   238→        let color = if i < colors.len() {
   239→            colors[i].clone()
   240→        } else {
   241→            "#50fa7b".to_string()
   242→        };
   243→        html.push_str(render_single_agent_card(data.deployment_state.agent_statuses[i].clone(), color).as_str());
   244→    }
   245→
   246→    html.push_str("  </div>\n");
   247→    html
   248→}
   249→
   250→fn render_metrics_section(data: DashboardData) -> String {
   251→    let mut html = String::new();
   252→    html.push_str("  <div class=\"metrics\">\n");
   253→    html.push_str("    <h2>실시간 메트릭</h2>\n");
   254→    html.push_str("    <pre>\n");
   255→
   256→    let success_rate = if data.aggregated_metrics.total_executions > 0 {
   257→        ((data.aggregated_metrics.success_count as f32) / (data.aggregated_metrics.total_executions as f32)) * 100.0f32
   258→    } else {
   259→        0.0f32
   260→    };
   261→
   262→    html.push_str(render_ascii_bar("성공률".to_string(), success_rate, 100.0f32, 20i32).as_str());
   263→    html.push_str(render_ascii_bar("학습률".to_string(), data.aggregated_metrics.avg_learning_rate * 100.0f32, 100.0f32, 20i32).as_str());
   264→    html.push_str(render_ascii_bar("치료율".to_string(), data.aggregated_metrics.avg_healing_rate, 100.0f32, 20i32).as_str());
   265→
   266→    html.push_str("    </pre>\n");
   267→    html.push_str("    <div>총 실행: ");
   268→    html.push_str(&data.aggregated_metrics.total_executions.to_string());
   269→    html.push_str(" | 성공: ");
   270→    html.push_str(&data.aggregated_metrics.success_count.to_string());
   271→    html.push_str(" | 실패: ");
   272→    html.push_str(&data.aggregated_metrics.failure_count.to_string());
   273→    html.push_str(" | 평균시간: ");
   274→    html.push_str(&data.aggregated_metrics.avg_execution_time_ms.to_string());
   275→    html.push_str("ms</div>\n");
   276→    html.push_str("  </div>\n");
   277→    html
   278→}
   279→
   280→fn render_history_table(records: Vec<ExecutionRecord>) -> String {
   281→    let mut html = String::new();
   282→    html.push_str("  <table>\n");
   283→    html.push_str("    <tr><th>#</th><th>Intent</th><th>성공</th><th>패치</th><th>치료율</th><th>시간</th></tr>\n");
   284→
   285→    for i in 0..records.len() {
   286→        html.push_str("    <tr>\n");
   287→        html.push_str("      <td>");
   288→        html.push_str(&records[i].record_id.to_string());
   289→        html.push_str("</td>\n");
   290→        html.push_str("      <td>");
   291→        html.push_str(records[i].user_intent.as_str());
   292→        html.push_str("</td>\n");
   293→        html.push_str("      <td>");
   294→        html.push_str(if records[i].success { "✅" } else { "❌" });
   295→        html.push_str("</td>\n");
   296→        html.push_str("      <td>");
   297→        html.push_str(&records[i].patches_applied.to_string());
   298→        html.push_str("</td>\n");
   299→        html.push_str("      <td>");
   300→        html.push_str(&records[i].healing_success_rate.to_string());
   301→        html.push_str("</td>\n");
   302→        html.push_str("      <td>");
   303→        html.push_str(&records[i].execution_time_ms.to_string());
   304→        html.push_str("ms</td>\n");
   305→        html.push_str("    </tr>\n");
   306→    }
   307→
   308→    html.push_str("  </table>\n");
   309→    html
   310→}
   311→
   312→fn render_quick_test_form(config: DashboardConfig) -> String {
   313→    let mut html = String::new();
   314→    html.push_str("  <div class=\"quick-test\">\n");
   315→    html.push_str("    <h2>빠른 파이프라인 테스트</h2>\n");
   316→    html.push_str("    <input id=\"intent\" placeholder=\"예: 더하기 5 10\" />\n");
   317→    html.push_str("    <button onclick=\"runPipeline()\">실행</button>\n");
   318→    html.push_str("    <pre id=\"result\"></pre>\n");
   319→    html.push_str("  </div>\n");
   320→    html
   321→}
   322→
   323→fn render_javascript_polling(config: DashboardConfig) -> String {
   324→    let mut js = String::new();
   325→    js.push_str("  <script>\n");
   326→    js.push_str("    setInterval(function() {\n");
   327→    js.push_str("      fetch('");
   328→    js.push_str(config.api_base_url.as_str());
   329→    js.push_str("/metrics')\n");
   330→    js.push_str("        .then(r => r.json())\n");
   331→    js.push_str("        .then(data => {\n");
   332→    js.push_str("          console.log('Metrics updated', data);\n");
   333→    js.push_str("        });\n");
   334→    js.push_str("    }, ");
   335→    js.push_str(&(config.refresh_interval_sec * 1000).to_string());
   336→    js.push_str(");\n");
   337→    js.push_str("    function runPipeline() {\n");
   338→    js.push_str("      const intent = document.getElementById('intent').value;\n");
   339→    js.push_str("      fetch('");
   340→    js.push_str(config.api_base_url.as_str());
   341→    js.push_str("/pipeline?intent=' + encodeURIComponent(intent))\n");
   342→    js.push_str("        .then(r => r.json())\n");
   343→    js.push_str("        .then(data => {\n");
   344→    js.push_str("          document.getElementById('result').textContent = JSON.stringify(data, null, 2);\n");
   345→    js.push_str("        })\n");
   346→    js.push_str("        .catch(e => {\n");
   347→    js.push_str("          document.getElementById('result').textContent = 'Error: ' + e.message;\n");
   348→    js.push_str("        });\n");
   349→    js.push_str("    }\n");
   350→    js.push_str("  </script>\n");
   351→    js
   352→}
   353→
   354→fn render_full_dashboard(data: DashboardData, config: DashboardConfig) -> String {
   355→    let mut html = String::new();
   356→    html.push_str("<body style=\"background: ");
   357→    html.push_str(config.theme_bg.as_str());
   358→    html.push_str("; color: #f8f8f2; font-family: monospace;\">\n");
   359→    html.push_str(render_css_styles(config.clone()).as_str());
   360→    html.push_str(render_header_section(data.clone()).as_str());
   361→    html.push_str(render_agent_cards_section(data.clone()).as_str());
   362→    html.push_str(render_metrics_section(data.clone()).as_str());
   363→    html.push_str("  <h2>최근 실행 히스토리</h2>\n");
   364→    html.push_str(render_history_table(data.clone().recent_history).as_str());
   365→    html.push_str(render_quick_test_form(config.clone()).as_str());
   366→    html.push_str(render_javascript_polling(config.clone()).as_str());
   367→    html.push_str("</body>\n");
   368→    html.push_str("</html>\n");
   369→    html
   370→}
   371→
   372→// ===== Public API =====
   373→
   374→fn create_dashboard_generator() -> DashboardConfig {
   375→    create_dashboard_config()
   376→}
   377→
   378→fn create_dashboard_data(state: DeploymentState, metrics: AggregatedMetrics, history: Vec<ExecutionRecord>) -> DashboardData {
   379→    DashboardData {
   380→        deployment_state: state,
   381→        aggregated_metrics: metrics,
   382→        recent_history: history,
   383→        pipeline_health: state.pipeline_health
   384→    }
   385→}
   386→
   387→fn generate_dashboard_html(state: DeploymentState, metrics: AggregatedMetrics, history: Vec<ExecutionRecord>) -> String {
   388→    let config = create_dashboard_config();
   389→    let data = create_dashboard_data(state, metrics, history);
   390→    let head = render_html_head(config.clone());
   391→    let body = render_full_dashboard(data, config);
   392→    let mut html = String::new();
   393→    html.push_str(head.as_str());
   394→    html.push_str(body.as_str());
   395→    html
   396→}
