     4→// ===== Deployment Data Structures =====
     5→
     6→struct ServiceInfo {
     7→    service_name: String,
     8→    version: String,
     9→    host: String,
    10→    port: i32,
    11→    environment: String
    12→}
    13→
    14→trait ServiceInfoCl {
    15→    fn clone(&self) -> ServiceInfo;
    16→}
    17→
    18→impl ServiceInfoCl for ServiceInfo {
    19→    fn clone(&self) -> ServiceInfo {
    20→        ServiceInfo {
    21→            service_name: self.service_name.clone(),
    22→            version: self.version.clone(),
    23→            host: self.host.clone(),
    24→            port: self.port,
    25→            environment: self.environment.clone()
    26→        }
    27→    }
    28→}
    29→
    30→struct AgentStatus {
    31→    agent_name: String,
    32→    status: String,
    33→    last_execution: String,
    34→    success_rate: f32,
    35→    total_executions: i32
    36→}
    37→
    38→trait AgentStatusCl {
    39→    fn clone(&self) -> AgentStatus;
    40→}
    41→
    42→impl AgentStatusCl for AgentStatus {
    43→    fn clone(&self) -> AgentStatus {
    44→        AgentStatus {
    45→            agent_name: self.agent_name.clone(),
    46→            status: self.status.clone(),
    47→            last_execution: self.last_execution.clone(),
    48→            success_rate: self.success_rate,
    49→            total_executions: self.total_executions
    50→        }
    51→    }
    52→}
    53→
    54→struct DeploymentState {
    55→    service_info: ServiceInfo,
    56→    agent_statuses: Vec<AgentStatus>,
    57→    is_healthy: bool,
    58→    pipeline_health: f32,
    59→    total_pipeline_runs: i32
    60→}
    61→
    62→trait DeploymentStateCl {
    63→    fn clone(&self) -> DeploymentState;
    64→}
    65→
    66→impl DeploymentStateCl for DeploymentState {
    67→    fn clone(&self) -> DeploymentState {
    68→        let mut cloned_agents = vec![];
    69→        for i in 0..self.agent_statuses.len() {
    70→            cloned_agents.push(self.agent_statuses[i].clone());
    71→        }
    72→        DeploymentState {
    73→            service_info: self.service_info.clone(),
    74→            agent_statuses: cloned_agents,
    75→            is_healthy: self.is_healthy,
    76→            pipeline_health: self.pipeline_health,
    77→            total_pipeline_runs: self.total_pipeline_runs
    78→        }
    79→    }
    80→}
    81→
