   129→fn get_recent_records(store: MetricsStore, limit: i32) -> Vec<ExecutionRecord> {
   130→    let mut result = vec![];
   131→    let start = if store.records.len() > (limit as usize) {
   132→        store.records.len() - (limit as usize)
   133→    } else {
   134→        0
   135→    };
   136→
   137→    for i in start..store.records.len() {
   138→        result.push(store.records[i].clone());
   139→    }
   140→    result
   141→}
   142→
   143→fn calculate_aggregated_metrics(store: MetricsStore) -> AggregatedMetrics {
   144→    let total = store.records.len() as i32;
   145→    let mut success_count = 0i32;
   146→    let mut healing_sum = 0.0f32;
   147→    let mut learning_sum = 0.0f32;
   148→    let mut time_sum = 0i32;
   149→    let mut patch_sum = 0i32;
   150→
   151→    for i in 0..store.records.len() {
   152→        if store.records[i].success {
   153→            success_count = success_count + 1;
   154→        }
   155→        healing_sum = healing_sum + store.records[i].healing_success_rate;
   156→        learning_sum = learning_sum + store.records[i].learning_rate;
   157→        time_sum = time_sum + store.records[i].execution_time_ms;
   158→        patch_sum = patch_sum + store.records[i].patches_applied;
   159→    }
   160→
   161→    let avg_healing = if total > 0 { healing_sum / (total as f32) } else { 0.0f32 };
   162→    let avg_learning = if total > 0 { learning_sum / (total as f32) } else { 0.0f32 };
   163→    let avg_time = if total > 0 { time_sum / total } else { 0i32 };
   164→
   165→    AggregatedMetrics {
   166→        total_executions: total,
   167→        success_count: success_count,
   168→        failure_count: total - success_count,
   169→        avg_healing_rate: avg_healing,
   170→        avg_learning_rate: avg_learning,
   171→        avg_execution_time_ms: avg_time,
   172→        total_patches_applied: patch_sum,
   173→        uptime_seconds: 3600i32
   174→    }
   175→}
