   121→    fn execute_code_generator(&mut self, graph: ExecutionGraph) -> GeneratedCode {
   122→        let code = generate_fvlang_code(graph);
   123→
   124→        let msg = process_generated_code(code.clone());
   125→        self.message_bus.enqueue_message(msg);
   126→        self.message_bus.record_success();
   127→
   128→        code
   129→    }
