    90→            expected_success_rate: 80.0f32
    91→        });
    92→
    93→        // Scenario 2: 복합 변환 작업
    94→        steps.push(ScenarioStep {
    95→            step_id: 2,
    96→            description: "문자열 변환: 대문자 변환".to_string(),
    97→            user_intent: "변환 hello world".to_string(),
    98→            expected_patches: 2,
    99→            expected_success_rate: 85.0f32
   100→        });
   101→
   102→        // Scenario 3: 데이터 필터링
   103→        steps.push(ScenarioStep {
   104→            step_id: 3,
   105→            description: "필터링: 양수만 추출".to_string(),
   106→            user_intent: "필터 음수 양수 제거".to_string(),
   107→            expected_patches: 2,
   108→            expected_success_rate: 82.0f32
   109→        });
   110→
   111→        // Scenario 4: 데이터 집계
   112→        steps.push(ScenarioStep {
   113→            step_id: 4,
   114→            description: "집계: 합계 계산".to_string(),
   115→            user_intent: "집계 모든 숫자 합하기".to_string(),
   116→            expected_patches: 2,
   117→            expected_success_rate: 78.0f32
   118→        });
   119→
   120→        // Scenario 5: 제어 흐름
   121→        steps.push(ScenarioStep {
   122→            step_id: 5,
   123→            description: "제어: 반복 처리".to_string(),
   124→            user_intent: "반복 열번 실행".to_string(),
   125→            expected_patches: 3,
   126→            expected_success_rate: 75.0f32
   127→        });
   128→
   129→        ComplexExecutionEngine {
   130→            engine_id: engine_id,
   131→            scenario_steps: steps,
   132→            completed_scenarios: 0
   133→        }
   134→    }
   135→
   136→    fn execute_scenario(&mut self) -> ComplexScenario {
   137→        let mut all_intents = vec![];
   138→        let mut all_results = vec![];
   139→        let mut total_patches = 0i32;
   140→        let mut total_success_sum = 0.0f32;
   141→
   142→        for i in 0..self.scenario_steps.len() {
   143→            let step = &self.scenario_steps[i];
   144→
   145→            // Intent 실행
   146→            all_intents.push(step.user_intent.clone());
   147→
   148→            // 파이프라인 실행
   149→            let result = run_agent_pipeline(step.user_intent.clone());
   150→            all_results.push(result.clone());
   151→
   152→            total_patches = total_patches + result.patches_applied;
   153→            total_success_sum = total_success_sum + result.healing_success_rate;
   154→        }
   155→
   156→        self.completed_scenarios = self.completed_scenarios + 1;
   157→
   158→        let avg_success = total_success_sum / (self.scenario_steps.len() as f32);
   159→        let total_learning = 0.057f32 * (self.scenario_steps.len() as f32) * 0.01f32;
   160→
   161→        ComplexScenario {
   162→            scenario_id: format!("scenario_{}", self.completed_scenarios),
   163→            user_intents: all_intents,
   164→            execution_results: all_results,
   165→            total_success_rate: avg_success,
   166→            total_learning_rate: total_learning
   167→        }
   168→    }
   169→
   170→    fn execute_with_recovery(&mut self) -> ComplexScenario {
   171→        // 첫 번째 실행
   172→        let scenario1 = self.execute_scenario();
   173→
   174→        // 두 번째 실행 (학습된 규칙으로 개선)
   175→        let scenario2 = self.execute_scenario();
   176→
   177→        // 평균화
   178→        let mut combined_results = vec![];
   179→        for i in 0..scenario1.execution_results.len() {
   180→            combined_results.push(scenario1.execution_results[i].clone());
   181→        }
   182→
   183→        let combined_success = (scenario1.total_success_rate + scenario2.total_success_rate) / 2.0f32;
   184→        let combined_learning = scenario1.total_learning_rate + scenario2.total_learning_rate;
   185→
   186→        ComplexScenario {
   187→            scenario_id: "combined_scenario".to_string(),
   188→            user_intents: scenario1.user_intents,
   189→            execution_results: combined_results,
   190→            total_success_rate: combined_success,
   191→            total_learning_rate: combined_learning
   192→        }
   193→    }
   194→
   195→    fn get_step_count(&self) -> i32 {
   196→        self.scenario_steps.len() as i32
   197→    }
   198→
   199→    fn get_completed_count(&self) -> i32 {
   200→        self.completed_scenarios
   201→    }
   202→}
